def validPalindrome(s):
    def is_pal(sub, l, r):
        while l < r:
            if sub[l] != sub[r]: return False
            l += 1
            r -= 1
        return True
    left, right = 0, len(s) - 1
    while left < right:
        if s[left] != s[right]:
            return is_pal(s, left + 1, right) or is_pal(s, left, right - 1)
        left += 1
        right -= 1
    return True

